input.command:
cd /Users/raman/projects/lock_code_manager.wiki && python3 - <<'PYEOF'
import re
from pathlib import Path
def slug(h):
    h = h.strip().lower()
    h = re.sub(r"[^\w\- ]", "", h)  # drop punctuation except - and _
    return h.replace(" ", "-")
slugs = {}
for name in ["Provider-State-Management", "Adding-a-Provider", "Architecture"]:
    text = Path(name + ".md").read_text()
    text_nocode = re.sub(r"```.*?```", "", text, flags=re.S)
    slugs[name] = {slug(m.group(2)) for m in re.finditer(r"^(#{1,6}) (.+)$", text_nocode, re.M)}
bad = 0
for name in slugs:
    text = Path(name + ".md").read_text()
    for m in re.finditer(r"\[\[[^\]|]*\|([\w-]+)#([\w-]+)\]\]", text):
        ok = m.group(2) in slugs[m.group(1)]
        print(name, "->", m.group(1) + "#" + m.group(2), "OK" if ok else "MISSING"); bad += not ok
    for m in re.finditer(r"\]\(#([\w-]+)\)", text):
        ok = m.group(1) in slugs[name]
        print(name, "-> #" + m.group(1), "OK" if ok else "MISSING"); bad += not ok
print("bad:", bad)
PYEOF

